// Two-step intent classifier:
// 1. If the message starts with a slash command (/note, /ask, /summary), trust it.
// 2. Otherwise default to 'ask', Claude can always reply, but Memory still gets searched first.
//
// You can later replace this with a Claude-Haiku classifier for fuzzier intents.

const body = $input.first().json;
const message = body?.message ?? body;
const text = (message?.text ?? message?.caption ?? '').trim();
const chatId = message?.chat?.id;
const userId = message?.from?.id;

// User-label fallback chain: username > first_name > tg:userId > chat:chatId
// We never produce 'user-undefined' which would collapse channel posts and
// forwarded messages without sender into one shared identity.
let userLabel;
if (message?.from?.username) {
  userLabel = `@${message.from.username}`;
} else if (message?.from?.first_name) {
  userLabel = message.from.first_name;
} else if (userId !== undefined && userId !== null) {
  userLabel = `tg:${userId}`;
} else if (chatId !== undefined && chatId !== null) {
  userLabel = `chat:${chatId}`;
} else {
  throw new Error('Cannot identify user: message has no from.username, no from.first_name, no from.id, and no chat.id');
}

let intent = 'ask';
let payload = text;

const slashMatch = text.match(/^\/(note|ask|summary)\s+([\s\S]*)$/i);
if (slashMatch) {
  intent = slashMatch[1].toLowerCase();
  payload = slashMatch[2].trim();
} else if (/^\/(note|ask|summary)$/i.test(text)) {
  // Slash command without payload
  intent = text.slice(1).toLowerCase();
  payload = '';
}

return [{
  json: {
    intent,
    payload,
    rawText: text,
    chatId,
    userId,
    userLabel,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a context-aware prompt for Claude using whatever memory returned.

const question = $('Detect Intent').item.json.payload;
const userLabel = $('Detect Intent').item.json.userLabel;

const memData = $input.first().json;
const results = memData?.results ?? memData?.data?.results ?? [];

const contextLines = results.slice(0, 8).map((r, i) => {
  const text = r.content ?? r.text ?? r.formatted ?? JSON.stringify(r).slice(0, 200);
  const date = r.date ?? r.createdAt ?? '';
  return `${i + 1}. [${date}] ${text}`;
});

const contextBlock = contextLines.length
  ? contextLines.join('\n')
  : '(no prior context found in memory for this query)';

const systemPrompt = `You are ${userLabel}'s long-term memory and personal assistant. You have access to everything they've ever told you (notes, decisions, observations).\n\nMemory results for the current question:\n${contextBlock}\n\nReply concisely and reference specific past entries when relevant (e.g. "On March 12 you said..."). If the memory doesn't have a direct answer, say so honestly and offer to record the question as a note for future reference.`;

return [{
  json: {
    question,
    userLabel,
    contextBlock,
    systemPrompt,
    memoryHits: results.length,
  },
}];

// Normalize LLM output across providers into a single field `replyText`.
// OpenAI:    $json.choices[0].message.content
// Anthropic: $json.content[0].text

const raw = $input.first().json;
let replyText = '';

if (raw?.choices?.[0]?.message?.content) {
  replyText = raw.choices[0].message.content;
} else if (Array.isArray(raw?.content) && raw.content[0]?.text) {
  replyText = raw.content[0].text;
} else if (raw?.message?.content) {
  replyText = raw.message.content;
} else if (raw?.text) {
  replyText = raw.text;
} else if (raw?.reply) {
  replyText = raw.reply;
} else {
  replyText = '(LLM returned no text, check provider response shape)';
}

return [{
  json: {
    replyText: String(replyText).trim(),
    provider: $('Set Provider').item.json.provider,
  },
}];

// Webhook integrity check (opt-in via WEBHOOK_INTEGRITY_CHECK_ENABLED=1).
// Telegram Trigger handles HMAC via its secretToken option (set on the
// trigger node itself). This Code node is the second defense layer:
// reject malformed payloads that lack the fields downstream nodes expect.
//
// To enable: set the n8n env var WEBHOOK_INTEGRITY_CHECK_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.

const enabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;

if (!message || typeof message !== 'object') {
  throw new Error('Webhook integrity check failed: no message object');
}
if (typeof message.chat?.id !== 'number' && typeof message.chat?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.chat.id');
}
if (typeof message.text !== 'string' && typeof message.caption !== 'string') {
  throw new Error('Webhook integrity check failed: no text or caption');
}

return [{ json: item }];

// Rate limit (opt-in via RATE_LIMIT_ENABLED=1).
// Per-chat-id 60 requests in a 5-minute window. Tracked in workflow
// static data (per-instance). For clustered n8n deployments or higher
// throughput, use Nginx limit_req_zone or Cloudflare WAF instead.
//
// To enable: set the n8n env var RATE_LIMIT_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic. Under heavy
// burst load the count can over-shoot the limit by a few percent. For
// hard limits use a reverse proxy or Redis INCR + EXPIRE.

const enabled = $env.RATE_LIMIT_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const chatId = message?.chat?.id ?? message?.from?.id ?? 'unknown';
const bucketKey = `chat:${chatId}`;

const data = $getWorkflowStaticData('global');
const buckets = data.rateBuckets ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const LIMIT = 60;
const MAX_BUCKETS = 5000;

const bucket = buckets[bucketKey] ?? { count: 0, windowStart: now };
if (now - bucket.windowStart > WINDOW_MS) {
  bucket.count = 0;
  bucket.windowStart = now;
}
bucket.count++;
buckets[bucketKey] = bucket;

if (Object.keys(buckets).length > MAX_BUCKETS) {
  const cutoff = now - WINDOW_MS;
  for (const k of Object.keys(buckets)) {
    if (buckets[k].windowStart < cutoff) delete buckets[k];
  }
}
data.rateBuckets = buckets;

if (bucket.count > LIMIT) {
  throw new Error(`Rate limit exceeded for ${bucketKey}: ${bucket.count} requests in 5 min window`);
}

return [{ json: item }];

// Idempotency check (opt-in via IDEMPOTENCY_ENABLED=1).
// Telegram retries on 5xx. Without dedup, the workflow fires twice and
// writes Memory twice. This node holds a 5-minute in-memory window of
// seen update_ids and short-circuits duplicates.
//
// To enable: set the n8n env var IDEMPOTENCY_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic and not cluster-
// aware. For production scale, swap the staticData block for Redis SET NX
// EX 300 (atomic, cluster-aware, auto-expires).

const enabled = $env.IDEMPOTENCY_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const updateId = item?.update_id ?? message?.update_id;
const messageId = message?.message_id;
const idempotencyKey = updateId ? `tg-update:${updateId}` : (messageId ? `tg-msg:${messageId}` : null);

if (!idempotencyKey) {
  return [{ json: item }];
}

const data = $getWorkflowStaticData('global');
const seen = data.seenKeys ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}

if (seen[idempotencyKey]) {
  return [];
}
seen[idempotencyKey] = now;
data.seenKeys = seen;

return [{ json: item }];

// LLM Fallback Reply: fires when OpenAI Reply or Anthropic Reply errors,
// or when Route by Provider receives an unknown provider value.
// Builds a graceful customer-facing reply and an error-learn payload.
//
// The error pin from a node with onError=continueErrorOutput delivers
// $json.error.message (and other error fields). $error.message does not
// exist as a global in n8n, despite being often quoted online.
//
// Two arrival paths land here:
//   1. LLM error (OpenAI or Anthropic returned non-2xx) ,  input has $json.error
//   2. Router fallback (Route by Provider had no matching rule) ,  input has
//      the original prompt object (systemPrompt, question, userLabel, etc.)
//      WITHOUT an error field. We must NOT JSON.stringify the whole input
//      because systemPrompt contains private user-memory context that would
//      then end up in the Memory: Learn Error audit trail.

const errorRaw = $input.first().json;
const provider = $('Set Provider').item.json.provider ?? 'unknown';

// Detect whether this is an error envelope or a router-fallback object
const isLlmError = !!(errorRaw?.error || errorRaw?.message);
let errorMessage;
if (isLlmError) {
  errorMessage = errorRaw?.error?.message
    ?? errorRaw?.error?.name
    ?? errorRaw?.message
    ?? 'Unknown LLM error';
} else {
  // Router fallback: the input has no error field. Synthesize a clean
  // diagnostic that does not leak systemPrompt or any private context.
  errorMessage = `Unknown provider value: ${provider}. Set "provider" to "openai" or "anthropic" in the Set Provider node.`;
}

const userLabel = $('Detect Intent').item.json.userLabel;
const question = $('Detect Intent').item.json.payload;
const chatId = $('Detect Intent').item.json.chatId;

const fallbackText = `Sorry, I had trouble looking that up just now. Try again in a minute, or send /note <your question> to record it for later.`;

return [{
  json: {
    replyText: fallbackText,
    provider,
    isFallback: true,
    isRouterFallback: !isLlmError,
    errorMessage: String(errorMessage),
    userLabel,
    question,
    chatId,
  },
}];
